    34|function sh(cmd: string, args: string[], timeoutMs: number): Promise<{ stdout: string; code: number }> {
    35|  return new Promise((resolve) => {
    36|    execFile(cmd, args, { cwd: repoRoot, timeout: timeoutMs, maxBuffer: 64 * 1024 * 1024 }, (err, stdout, stderr) => {
    37|      const out = `${stdout ?? ''}${stderr ?? ''}`;
    38|      const code = err && typeof (err as { code?: number }).code === 'number' ? (err as { code: number }).code : err ? 1 : 0;
    39|      resolve({ stdout: out, code });
    40|    });
    41|  });
    42|}
