    44|/** Shared repository gates. Run once; every agent inherits the real result. */
    45|async function runSharedGates(): Promise<SharedGate[]> {
    46|  const gates: SharedGate[] = [];
    47|
    48|  const tsc = await sh('bunx', ['tsc', '--noEmit'], 600_000);
    49|  const tscParsed = parseTscOutput(tsc.stdout);
    50|  gates.push({
    51|    name: 'typecheck',
    52|    passed: tscParsed.errorCount === 0,
    53|    detail: `${tscParsed.errorCount} TypeScript error(s)`,
    54|    evidence: { errorCount: tscParsed.errorCount, firstErrors: tscParsed.firstErrors.slice(0, 5), exitCode: tsc.code },
    55|  });
    56|
    57|  const tests = await sh('bun', ['test', 'backend'], 900_000);
    58|  const testParsed = parseBunTestOutput(tests.stdout);
    59|  const failingNames = Array.from(
    60|    new Set(
    61|      tests.stdout
    62|        .split('\n')
    63|        .filter((l) => l.startsWith('(fail)'))
    64|        .map((l) => l.replace(/\s\[[0-9.]+ms\]$/, '').trim()),
    65|    ),
    66|  );
    67|  gates.push({
    68|    name: 'tests',
    69|    passed: failingNames.length === 0 && testParsed.pass > 0,
    70|    detail: `${failingNames.length} unique failing test name(s); counters ${testParsed.pass} pass / ${testParsed.fail} fail`,
    71|    evidence: {
    72|      uniqueFailingTestNames: failingNames.length,
    73|      sampleFailing: failingNames.slice(0, 10),
    74|      countersNote: 'Raw counters are non-deterministic across runs; unique failing NAMES are the stable metric.',
    75|    },
    76|  });
    77|
    78|  const secret = await executeEngineeringTool('secret_scan', {}, { repoRoot });
    79|  gates.push({
    80|    name: 'secret_scan',
    81|    passed: secret.ok && secret.extract.matchedFileCount === 0,
    82|    detail: secret.ok ? `${String(secret.extract.matchedFileCount)} file(s) matched secret patterns (names only)` : `tool error: ${secret.error}`,
    83|    evidence: { matchedFileCount: secret.extract.matchedFileCount ?? null, contentSha256: secret.contentSha256 },
    84|  });
    85|
    86|  return gates;
    87|}
