    89|type AgentIdentity = { agentNumber: number; agentId: string; agentName: string; role: string };
    90|
    91|async function loadRoster(): Promise<AgentIdentity[]> {
    92|  const dir = path.join(repoRoot, 'qa/evidence/autonomous/agents');
    93|  const files = (await readdir(dir)).filter((f) => /^agent-\d{3}\.json$/.test(f)).sort();
    94|  const out: AgentIdentity[] = [];
    95|  for (const f of files) {
    96|    const d = JSON.parse(await readFile(path.join(dir, f), 'utf8')) as Record<string, unknown>;
    97|    out.push({
    98|      agentNumber: Number(d.agentNumber),
    99|      agentId: String(d.agentId ?? ''),
   100|      agentName: String(d.agentName ?? ''),
   101|      role: String(d.role ?? ''),
   102|    });
   103|  }
   104|  return out;
   105|}
