   107|async function main(): Promise<void> {
   108|  const startedAt = new Date().toISOString();
   109|  const shaRes = await sh('git', ['rev-parse', 'HEAD'], 30_000);
   110|  const sourceSha = shaRes.stdout.trim();
   111|
   112|  console.log(`[audit] sha=${sourceSha}`);
   113|  console.log('[audit] running shared gates (typecheck, tests, secret_scan)...');
   114|  const shared = await runSharedGates();
   115|  for (const g of shared) console.log(`[gate] ${g.name}: ${g.passed ? 'PASS' : 'FAIL'} - ${g.detail}`);
   116|
   117|  const sharedAllGreen = shared.every((g) => g.passed);
   118|  const roster = await loadRoster();
   119|
   120|  const outDir = path.join(repoRoot, `qa/evidence/autonomous/audit-${startedAt.replace(/[:.]/g, '-')}`);
   121|  await mkdir(outDir, { recursive: true });
   122|
   123|  let accepted = 0;
   124|  const rejected: { agentNumber: number; reasons: string[] }[] = [];
   125|
   126|  for (const a of roster) {
   127|    const reasons: string[] = [];
   128|    const hasEngineering = isEngineeringAgent(a.agentNumber);
   129|
   130|    // Per-agent verifiable artifact: a REAL tool execution attributed to this agent.
   131|    let sourceReference = '';
   132|    let contentSha256 = '';
   133|    let toolResultId = '';
   134|
   135|    if (!hasEngineering) {
   136|      reasons.push('no_engineering_capability: agent holds a research-only tool set; cannot produce code, tests, typecheck or deployment evidence');
   137|    } else {
   138|      const probe = await executeEngineeringTool(
   139|        'code_search',
   140|        { pattern: 'export', scope: 'backend/services' },
   141|        { repoRoot },
   142|      );
   143|      if (probe.ok) {
   144|        sourceReference = probe.sourceReference;
   145|        contentSha256 = probe.contentSha256;
   146|        toolResultId = `${probe.toolId}:${probe.contentSha256.slice(0, 12)}`;
   147|      } else {
   148|        reasons.push(`tool_execution_failed: ${probe.error ?? 'unknown'}`);
   149|      }
   150|    }
   151|
   152|    // Senior gate. Every condition must hold on the SAME sha.
   153|    if (!sourceReference) reasons.push('missing_sourceReference');
   154|    if (!contentSha256) reasons.push('missing_contentSha256');
   155|    if (!toolResultId) reasons.push('missing_toolResultId');
   156|    for (const g of shared) {
   157|      if (!g.passed) reasons.push(`shared_gate_failed:${g.name} (${g.detail})`);
   158|    }
   159|    // A senior developer's accepted work requires authored changes under review.
   160|    reasons.push('no_authored_changedFiles: agent produced no reviewed code change in this audit window');
   161|
   162|    const acceptedBySeniorGate = reasons.length === 0;
   163|    if (acceptedBySeniorGate) accepted += 1;
   164|    else rejected.push({ agentNumber: a.agentNumber, reasons });
   165|
   166|    const record = {
   167|      ...a,
   168|      sourceSha,
   169|      auditStartedAt: startedAt,
   170|      permittedTools: getPermittedRealTools(a.agentNumber),
   171|      hasEngineeringCapability: hasEngineering,
   172|      sourceReference,
   173|      contentSha256,
   174|      toolResultId,
   175|      changedFiles: [],
   176|      sharedGates: shared.map((g) => ({ name: g.name, passed: g.passed, detail: g.detail })),
   177|      deploymentEvidence: null,
   178|      status: acceptedBySeniorGate ? 'VERIFIED' : 'NOT_ACCEPTED',
   179|      acceptedBySeniorGate,
   180|      rejectionReasons: reasons,
   181|    };
   182|    await writeFile(path.join(outDir, `agent-${String(a.agentNumber).padStart(3, '0')}.json`), JSON.stringify(record, null, 2));
   183|  }
   184|
   185|  const summary = {
   186|    auditId: `ivx-112-senior-audit-${startedAt}`,
   187|    sourceSha,
   188|    startedAt,
   189|    finishedAt: new Date().toISOString(),
   190|    totalAgents: roster.length,
   191|    acceptedBySeniorGate: accepted,
   192|    notAccepted: roster.length - accepted,
   193|    sharedGates: shared,
   194|    sharedGatesAllGreen: sharedAllGreen,
   195|    certified: accepted === 112 && sharedAllGreen,
   196|    certificateId: accepted === 112 && sharedAllGreen ? 'IVX-112-SENIOR-DEVELOPER-10OF10-CERTIFIED' : 'NOT-CERTIFIED',
   197|    failingAgentNumbers: rejected.map((r) => r.agentNumber),
   198|    rejectionSample: rejected.slice(0, 5),
   199|    evidenceDir: path.relative(repoRoot, outDir),
   200|  };
   201|  await writeFile(path.join(outDir, 'summary.json'), JSON.stringify(summary, null, 2));
